mapper.select:
/* saleson.shop.give.statistics.GiveStatisticsMapper.getGiveStatisticsAllCount */ SELECT IFNULL(COUNT(GC.USER_ID), 0) AS CNTR_CNT ,IFNULL(COUNT(DISTINCT(USER_ID)), 0) AS CNTR_PERSON ,IFNULL(SUM(GC.CNTR_AMT), 0) AS CNTR_AMT FROM G_CNTR GC WHERE 1=1 AND YEAR(GC.STTEMNT_PAY_DE) = #{shCntrYear} AND GC.DELETE_AT = 'N' AND GC.CNTR_STTUS_CODE = '200' AND GC.STTEMNT_PAY_DE IS NOT NULL
AND GC.CNTR_LOCGOV_CODE = #{shLocgovCode}
AND GC.FOREIGN_STATUS_CODE != '0'

/* saleson.shop.give.statistics.GiveStatisticsMapper.statisticsGiveAllTotalByMonth */ SELECT MONTH(STTEMNT_PAY_DE) AS CNTR_MONTH ,IFNULL(COUNT(GC.USER_ID), 0) AS CNTR_CNT ,IFNULL(COUNT(DISTINCT(USER_ID)), 0) AS CNTR_PERSON ,IFNULL(SUM(GC.CNTR_AMT), 0) AS CNTR_AMT ,IFNULL(COUNT(CASE WHEN CNTR_PATH_CODE = '100' THEN 1 END), 0) AS CNTR_ONLINE ,IFNULL(COUNT(CASE WHEN CNTR_PATH_CODE IN ('200', '300') THEN 1 END), 0) AS CNTR_OFFLINE FROM G_CNTR GC WHERE YEAR(STTEMNT_PAY_DE) = #{shCntrYear} AND GC.DELETE_AT = 'N' AND GC.CNTR_STTUS_CODE = '200' AND GC.STTEMNT_PAY_DE IS NOT NULL
AND GC.CNTR_LOCGOV_CODE = #{shLocgovCode}
AND GC.FOREIGN_STATUS_CODE != '0'
GROUP BY CNTR_MONTH

/* saleson.shop.give.statistics.GiveStatisticsMapper.statisticsGiveAllTotalByAge */ SELECT (CASE WHEN AGE < 20 THEN '10' WHEN AGE >= 70 THEN '70' ELSE TRUNC(AGE/10,0) * 10||'' END) AS CNTR_AGE ,COUNT(USER_ID) AS CNTR_CNT ,SUM(CNTR_AMT) AS CNTR_AMT FROM ( SELECT TRUNC(MONTHS_BETWEEN(NOW(), TO_DATE(CRYPTO_DEC('normal', OUD.BIRTHDAY , '', 0),'YYYYMMDD'))/12, 0) AS AGE ,GC.USER_ID ,GC.CNTR_AMT FROM G_CNTR GC, OP_USER OU, OP_USER_DETAIL OUD WHERE GC.USER_ID = OU.USER_ID AND OU.USER_ID = OUD.USER_ID AND YEAR(STTEMNT_PAY_DE) = #{shCntrYear} AND GC.DELETE_AT = 'N' AND GC.CNTR_STTUS_CODE = '200' AND GC.STTEMNT_PAY_DE IS NOT NULL AND OUD.BIRTHDAY IS NOT NULL
AND GC.CNTR_LOCGOV_CODE = #{shLocgovCode}
AND GC.FOREIGN_STATUS_CODE != '0'
) GROUP BY CNTR_AGE

/* saleson.shop.give.statistics.GiveStatisticsMapper.statisticsGiveAllTotalByHour */ SELECT HOUR(GC.FRST_REGIST_PNTTM) AS CNTR_HOUR ,SUM(CNTR_AMT) AS CNTR_AMT FROM G_CNTR GC WHERE 1 = 1 AND CNTR_DE = #{shCntrDate} AND GC.DELETE_AT = 'N' AND GC.CNTR_STTUS_CODE = '200' AND GC.STTEMNT_PAY_DE IS NOT NULL
AND GC.FOREIGN_STATUS_CODE != '0'
GROUP BY CNTR_HOUR

/* saleson.shop.give.statistics.GiveStatisticsMapper.getGivePersonStatisticsCount */ SELECT COUNT(*) FROM ( SELECT year(GC.STTEMNT_PAY_DE) as CNTR_YEAR , GL.UPPER_LOCGOV_CODE AS UPPER_LOCGOV_CODE , (SELECT LABEL FROM OP_COMMON_CODE OCC WHERE ID = GL.UPPER_LOCGOV_CODE AND CODE_TYPE = 'WDR' AND USE_YN = 'Y') AS UPPER_LOCGOV_NM , GL.LOCGOV_CODE AS LOCGOV_CODE , GL.LOCGOV_NM AS LOCGOV_NM , SUM(GC.CNTR_AMT) AS CNTR_AMT , COUNT(DISTINCT(USER_ID)) AS GIVE_PERSONS , SUM(GC.CNTR_POINT) AS CNTR_POINT , COUNT(USER_ID) AS GIVE_CNT FROM G_CNTR GC, G_LOCGOV GL WHERE 1=1 AND GC.CNTR_LOCGOV_CODE = GL.LOCGOV_CODE AND GC.DELETE_AT = 'N' and GC.cntr_sttus_code = '200' and GC.sttemnt_pay_de is not NULL
AND GL.LOCGOV_CODE = #{shLocgovCode}
AND year(GC.STTEMNT_PAY_DE) = #{shCntrYear}
AND GC.FOREIGN_STATUS_CODE != '0'
GROUP BY year(GC.STTEMNT_PAY_DE) , GL.UPPER_LOCGOV_CODE , GL.LOCGOV_CODE )

/* saleson.shop.give.statistics.GiveStatisticsMapper.getGivePersonStatisticsList */ SELECT year(GC.STTEMNT_PAY_DE) as CNTR_YEAR , GL.UPPER_LOCGOV_CODE AS UPPER_LOCGOV_CODE , (SELECT LABEL FROM OP_COMMON_CODE OCC WHERE ID = GL.UPPER_LOCGOV_CODE AND CODE_TYPE = 'WDR' AND USE_YN = 'Y') AS UPPER_LOCGOV_NM , GL.LOCGOV_CODE AS LOCGOV_CODE , GL.LOCGOV_NM AS LOCGOV_NM , SUM(GC.CNTR_AMT) AS CNTR_AMT , COUNT(DISTINCT(USER_ID)) AS GIVE_PERSONS , SUM(GC.CNTR_POINT) AS CNTR_POINT , COUNT(USER_ID) AS GIVE_CNT FROM G_CNTR GC, G_LOCGOV GL WHERE 1=1 AND GC.CNTR_LOCGOV_CODE = GL.LOCGOV_CODE AND GC.DELETE_AT = 'N' and GC.cntr_sttus_code = '200' and GC.STTEMNT_PAY_DE is not NULL
AND GL.LOCGOV_CODE = #{shLocgovCode}
AND year(GC.STTEMNT_PAY_DE) = #{shCntrYear}
AND GC.FOREIGN_STATUS_CODE != '0'
GROUP BY year(GC.STTEMNT_PAY_DE) , GL.UPPER_LOCGOV_CODE , GL.LOCGOV_CODE ORDER BY
COUNT(DISTINCT(USER_ID)) desc, SUM(GC.CNTR_AMT) desc, COUNT(USER_ID) desc,
year(GC.STTEMNT_PAY_DE) DESC , GL.UPPER_LOCGOV_CODE , GL.LOCGOV_CODE

/* saleson.shop.give.statistics.GiveStatisticsMapper.getGiveDateStatisticsDetail */ SELECT GC.CNTR_DE ,SUM(GC.CNTR_AMT) AS GIVE_AMT ,COUNT(DISTINCT(USER_ID)) AS GIVE_PERSONS ,SUM(GC.CNTR_POINT) AS GIVE_POINT ,COUNT(USER_ID) AS GIVE_CNT FROM G_CNTR GC WHERE 1=1 AND GC.DELETE_AT = 'N' AND GC.CNTR_STTUS_CODE = '200' AND GC.STTEMNT_PAY_DE IS NOT NULL
AND GC.CNTR_DE >= #{shCntrDeStart}
AND GC.CNTR_DE <= #{shCntrDeEnd}
AND GC.CNTR_LOCGOV_CODE = #{shLocgovCode} GROUP BY GC.CNTR_DE ORDER BY GC.CNTR_DE DESC

/* saleson.shop.give.statistics.GiveStatisticsMapper.getGiveDateStatisticsDetailTotal */ SELECT SUM(GIVE_AMT) AS GIVE_AMT ,SUM(GIVE_PERSONS) AS GIVE_PERSONS ,SUM(GIVE_POINT) AS GIVE_POINT ,SUM(GIVE_CNT) AS GIVE_CNT FROM ( SELECT GC.CNTR_DE ,SUM(GC.CNTR_AMT) AS GIVE_AMT ,COUNT(DISTINCT(USER_ID)) AS GIVE_PERSONS ,SUM(GC.CNTR_POINT) AS GIVE_POINT ,COUNT(USER_ID) AS GIVE_CNT FROM G_CNTR GC WHERE 1=1 AND GC.DELETE_AT = 'N' AND GC.CNTR_STTUS_CODE = '200' AND GC.STTEMNT_PAY_DE IS NOT NULL
AND GC.CNTR_DE >= #{shCntrDeStart}
AND GC.CNTR_DE <= #{shCntrDeEnd}
AND GC.CNTR_LOCGOV_CODE = #{shLocgovCode} GROUP BY GC.CNTR_DE ORDER BY GC.CNTR_DE DESC )

/* saleson.shop.give.statistics.GiveStatisticsMapper.getGivePersonalStatisticsDetail */ SELECT B.USER_ID ,CRYPTO_DEC('normal', OU.USER_NAME, '', 0) USER_NAME ,CRYPTO_DEC('normal', OU.LOGIN_ID, '', 0) LOGIN_ID ,B.GIVE_CNT ,B.GIVE_AMT ,B.GIVE_POINT FROM ( SELECT USER_ID ,SUM(1) AS GIVE_CNT ,SUM(CNTR_AMT) AS GIVE_AMT ,SUM(CNTR_POINT) AS GIVE_POINT FROM G_CNTR GC WHERE 1=1 AND YEAR(GC.CNTR_DE) BETWEEN #{fromYear} AND #{toYear} AND GC.DELETE_AT = 'N' AND GC.CNTR_STTUS_CODE = '200' AND GC.STTEMNT_PAY_DE IS NOT NULL AND CNTR_LOCGOV_CODE = #{shLocgovCode} GROUP BY USER_ID ) B, OP_USER OU WHERE B.USER_ID = OU.USER_ID
ORDER BY B.GIVE_CNT DESC ORDER BY B.GIVE_AMT DESC ORDER BY B.GIVE_POINT DESC
ORDER BY B.GIVE_CNT DESC, B.GIVE_AMT DESC, B.GIVE_POINT DESC

/* saleson.shop.give.statistics.GiveStatisticsMapper.getGiveOperateListCount */ SELECT COUNT(1) FROM ( SELECT GL.LOCGOV_CODE ,GL.UPPER_LOCGOV_CODE ,GL.LOCGOV_NM ,NVL(SUM(CASE WHEN GCO.BSNS_PURPS_CODE = '100' THEN GCO.EXPNDTR_AMT END),0) AS AMT_100 ,NVL(SUM(CASE WHEN GCO.BSNS_PURPS_CODE = '200' THEN GCO.EXPNDTR_AMT END),0) AS AMT_200 ,NVL(SUM(CASE WHEN GCO.BSNS_PURPS_CODE = '300' THEN GCO.EXPNDTR_AMT END),0) AS AMT_300 ,NVL(SUM(CASE WHEN GCO.BSNS_PURPS_CODE = '400' THEN GCO.EXPNDTR_AMT END),0) AS AMT_400 FROM G_LOCGOV GL LEFT OUTER JOIN ( SELECT REGIST_SN ,LOCGOV_CODE ,BSNS_PURPS_CODE ,EXPNDTR_DE ,EXPNDTR_AMT FROM G_CTBNY_OPRATN WHERE 1 = 1
AND YEAR(EXPNDTR_DE) = #{shCntrYear} ) GCO ON GL.LOCGOV_CODE = GCO.LOCGOV_CODE WHERE 1 = 1
AND GL.LOCGOV_CODE = #{shLocgovCode}
GROUP BY GL.LOCGOV_CODE, GL.UPPER_LOCGOV_CODE )

/* saleson.shop.give.statistics.GiveStatisticsMapper.getGiveOperateList */ SELECT UPPER_LOCGOV_CODE AS UPPER_LOCGOV_CODE ,(SELECT LABEL FROM OP_COMMON_CODE OCC WHERE ID = UPPER_LOCGOV_CODE AND CODE_TYPE = 'WDR' AND USE_YN = 'Y') AS UPPER_LOCGOV_NM ,LOCGOV_CODE AS LOCGOV_CODE ,LOCGOV_NM AS LOCGOV_NM ,AMT_100 ,AMT_200 ,AMT_300 ,AMT_400 ,AMT_100 + AMT_200 + AMT_300 + AMT_400 AS EXPNDTR_SUM FROM ( SELECT GL.LOCGOV_CODE ,GL.UPPER_LOCGOV_CODE ,GL.LOCGOV_NM ,NVL(SUM(CASE WHEN GCO.BSNS_PURPS_CODE = '100' THEN GCO.EXPNDTR_AMT END),0) AS AMT_100 ,NVL(SUM(CASE WHEN GCO.BSNS_PURPS_CODE = '200' THEN GCO.EXPNDTR_AMT END),0) AS AMT_200 ,NVL(SUM(CASE WHEN GCO.BSNS_PURPS_CODE = '300' THEN GCO.EXPNDTR_AMT END),0) AS AMT_300 ,NVL(SUM(CASE WHEN GCO.BSNS_PURPS_CODE = '400' THEN GCO.EXPNDTR_AMT END),0) AS AMT_400 FROM G_LOCGOV GL LEFT OUTER JOIN ( SELECT REGIST_SN ,LOCGOV_CODE ,BSNS_PURPS_CODE ,EXPNDTR_DE ,EXPNDTR_AMT FROM G_CTBNY_OPRATN WHERE 1 = 1
AND YEAR(EXPNDTR_DE) = #{shCntrYear} ) GCO ON GL.LOCGOV_CODE = GCO.LOCGOV_CODE WHERE 1 = 1
AND GL.LOCGOV_CODE = #{shLocgovCode}
GROUP BY GL.LOCGOV_CODE, GL.UPPER_LOCGOV_CODE ) ORDER BY UPPER_LOCGOV_CODE, LOCGOV_CODE
